WITH joined AS ( SELECT sr.sr_return_amt, i.i_category, ca.ca_city FROM store_returns sr JOIN item i ON sr.sr_item_sk = i.i_item_sk JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk JOIN customer_address ca ON sr.sr_addr_sk = ca.ca_address_sk ), agg AS ( SELECT ca_city, i_category, SUM(sr_return_amt) AS total_return_amt, COUNT(*) AS return_cnt FROM joined GROUP BY ca_city, i_category ) SELECT ca_city, i_category, total_return_amt, return_cnt, CASE WHEN total_return_amt > 10000 THEN 'HIGH' WHEN total_return_amt > 5000 THEN 'MEDIUM' ELSE 'LOW' END AS return_level, RANK() OVER (PARTITION BY ca_city ORDER BY total_return_amt DESC) AS city_rank, DENSE_RANK() OVER (ORDER BY total_return_amt DESC) AS overall_rank FROM agg ORDER BY ca_city, overall_rank
